query:
/* groups: CHILD --> PARENT traversal */
declare
 @group nvarchar(1024) = 'Loans & Advances (Asset)';
with cte as
(
 select name, parent from mst_group where name = @group
 union all
 select e.name, e.parent from mst_group e inner join cte on cte.parent = e.name
)
select * from cte;

/* groups: PARENT --> CHILD traversal */
declare
 @group nvarchar(1024) = 'Loans & Advances (Asset)';
with cte as
(
 select name, parent from mst_group where name = @group
 union all
 select e.name, e.parent from mst_group e inner join cte on cte.name = e.parent
)
select * from cte;

WITH OrderedItems AS ( SELECT tv.voucher_number AS po_voucher_number, tv.date AS po_date, tv.party_name AS po_party_name, ti._item AS item_guid, mst_si.name AS item_name, SUM(ti.quantity) AS ordered_quantity, MAX(ti.order_duedate) AS order_duedate FROM trn_voucher tv JOIN mst_vouchertype mvt ON tv._voucher_type = mvt.guid JOIN trn_inventory ti ON tv.guid = ti.guid JOIN mst_stock_item mst_si ON ti._item = mst_si.guid WHERE mvt.parent = 'Purchase Order' AND tv.is_order_voucher = 1 AND tv.date BETWEEN '2025-04-01' AND '2026-05-30'
 -- AND mst_si.name = '28G11A0'
 GROUP BY tv.voucher_number, tv.date, tv.party_name, ti._item, mst_si.name ), ReceivedItems AS ( SELECT ti.order_number AS po_voucher_number, ti._item AS item_guid, SUM(ti.quantity) AS received_quantity FROM trn_voucher tv JOIN mst_vouchertype mvt ON tv._voucher_type = mvt.guid JOIN trn_inventory ti ON tv.guid = ti.guid WHERE mvt.parent = 'Receipt Note' AND tv.is_inventory_voucher = 1 AND tv.date BETWEEN '2025-04-01' AND '2026-03-31' GROUP BY ti.order_number, ti._item ) SELECT oi.po_voucher_number, oi.po_date, oi.po_party_name, oi.item_name, oi.ordered_quantity, COALESCE(ri.received_quantity, 0) AS received_quantity, (oi.ordered_quantity - COALESCE(ri.received_quantity, 0)) AS pending_quantity, oi.order_duedate FROM OrderedItems oi LEFT JOIN ReceivedItems ri ON oi.po_voucher_number = ri.po_voucher_number AND oi.item_guid = ri.item_guid WHERE (oi.ordered_quantity - COALESCE(ri.received_quantity, 0)) > 0 ORDER BY oi.po_date ASC, oi.po_voucher_number, oi.item_name;
